import logging
import re

from taf.hw.rf_attenuator.attenuator_class import Attenuator
from taf.hw.rf_attenuator.exceptions import InvalidUnit, AttenuationReadError
from taf.hw.rf_attenuator.utils.telnet import TelnetClient


class JFW(Attenuator):
    """Module to control JFW rf_attenuator"""
    DB_REGEX = r'(\d{1,})\s{0,}dB'
    PORT_NOT_EXIST_REGEX = r'((Attenuator number error)|(does not exist))'

    MAX_SUPPORTED_ATTENUATION = 127
    MIN_SUPPORTED_ATTENUATION = 0

    def __init__(self, ip, port, min_attenuation=None, max_attenuation=None, mode='ports'):
        super(JFW, self).__init__()
        self.ip = ip
        self.port = port
        self.telnet = TelnetClient()
        self.firmware_version = None
        self.conn = None
        self.is_connected = False
        self.mode = mode
        self.mode_singular = self.mode[0:-1]
        self.min_attenuation = self._validate_min_attenuation(min_attenuation, self.MIN_SUPPORTED_ATTENUATION)
        self.max_attenuation = self._validate_max_attenuation(max_attenuation, self.MAX_SUPPORTED_ATTENUATION)

    def connect(self, **kwargs):
        """
        Establish connection with attenuation controller
        allowing to change attenuation on specific RF-port of that device
        """
        if not self.is_connected:
            self.telnet.connect(self.ip, self.port)
            self.is_connected = True
            logging.info('Connection to JFW rf_attenuator established.')
            # catch banner text and motd message
            result = self.telnet.read_command_output("\r")
            logging.debug(f"Catched banner and motd messages: \r\n \"{result}\" ")
            system_identification = self.telnet.read_command_output(command="IDN")
            logging.info(f"System identification: {system_identification}")
            self.firmware_version = self._get_firmware_version(system_identification)
            if not self.firmware_version.startswith('3'):
                logging.info("Firmware version of given device is older than 3.x.x, consider update.")
        else:
            logging.info('JFW rf_attenuator already connected.')

    def disconnect(self, **kwargs):
        """
        Release connection with attenuation controller
        """
        self.telnet.close_connection()
        self.is_connected = False

    def _get_firmware_version(self, system_identification):
        words = system_identification.split()
        firmware_string = next(filter(lambda line: line.lower().startswith('firmware'), words), None)
        if firmware_string is None:
            return "Unknown"
        firmware_index = words.index(firmware_string) + 1
        return words[firmware_index]

    def _set_single_port_decibel_attenuation(self, port, attenuation_value):
        attenuation_value = int(attenuation_value)
        port = str(port)
        cmd = self._prepare_set_command(attenuation_value, port)
        self._write(cmd)
        logging.info(f"{self.mode_singular} ID {port} value set to {attenuation_value} dB.")

    def _set_multiple_ports_decibel_attenuation(self, rf_port_addresses, attenuation_values_db):
        set_multiple_attenuators_cmd = 'SA' if self.firmware_version.startswith('3') else 'SMA'
        join_char = ' ' if self.firmware_version.startswith('3') else ', '
        params_as_tuples = zip(rf_port_addresses, attenuation_values_db)
        params_as_string = join_char.join(['{} {}'.format(port, value) for port, value in params_as_tuples])
        cmd = "{} {}".format(set_multiple_attenuators_cmd, params_as_string)
        self._write(cmd)
        return cmd

    def _prepare_set_command(self, attenuation_value, rf_port_address):
        if self.mode == 'ports':
            cmd = "SA{} {}".format(rf_port_address, attenuation_value)
        else:
            cmd = "SB{} {}".format(rf_port_address, attenuation_value)
        return cmd

    def _write(self, cmd):
        self.telnet.write_command(cmd)

    def read_port_attenuation(self, port):
        if self.mode == 'blocks':
            output = self.telnet.read_command_output("RB" + str(port), read_method='until')
        else:
            output = self.telnet.read_command_output("RA" + str(port), read_method='until', read_flag='dB\r\n')
        logging.debug(output)
        re_out = re.search(self.DB_REGEX, output)
        if re_out:
            value_read = re_out.groups()[0]
            logging.info(f"Value read on port {port}: {value_read}")
        elif re.search(self.PORT_NOT_EXIST_REGEX, output):
            raise AttenuationReadError("Tried to read attenuation of port {}. Such port does not exist".format(port))
        else:
            raise AttenuationReadError("Could not read attenuation value for {} {}.".format(port, self.mode_singular))
        return int(value_read)

    def set_linear_fading_scenario(self, port, start_value, end_value, interval, unit):
        """
        Set an linear fading scenario.
        """
        return LinearFadingScenario(
            port=port,
            start_value=start_value,
            end_value=end_value,
            interval=interval,
            unit=unit,
        )

    def set_ports_fading_attenuation(self, set_fading_scenarios, timeout):
        """
        Set ports fading attenuation by scenarios.
        """
        ports_fading_command = [port_fading_scenario.command for port_fading_scenario in set_fading_scenarios]

        command = "FA" + " ".join(ports_fading_command)
        logging.debug("sent fading command:{}".format(command))
        output = self.telnet.write_and_read(command, read_method='until', read_flag='Fade Finished\r\n',
                                            timeout=timeout)
        logging.debug("command output={}".format(output))
        return output

    def escape_command(self):
        """
        Stop commands processing and clear the connections command buffer.
        """
        if self.firmware_version.startswith('3'):
            logging.debug("Send ESCAPE command")
            output = self.telnet.write_and_read("ESCAPE", read_method="eager", read_flag="Escaping, Clearing Buffer")
            logging.debug(f"command output={output}")
            return output
        else:
            raise NotImplementedError("Escape command is not supported for firmware version older than 3.x.x")


class LinearFadingScenario(object):
    """
    Fade attenuation from start value to end value (in dB) over certain time interval (in milliseconds or seconds)
    Step size defaults to attenuator's dB step size

    Notes:
        - Time interval can range from 1ms to 9999s
        - Fade Attenuator blocks command buffer once it has been started and release after process finish.
          Thus it is not possible to read port's value during the fading proccess under a single connection.
        - Use the escape_command to exit the fade

    """

    def __init__(self, port, start_value, end_value, interval, unit):
        self.port = int(port)
        self.start_value = int(start_value)
        self.end_value = int(end_value)
        self.interval = int(interval)

        if unit not in ["M", "S"]:
            raise InvalidUnit(unit)

        self.unit = unit

    @property
    def command(self):
        return "{port} {start_value} {end_value} {interval}{unit}".format(
            port=self.port, start_value=self.start_value, end_value=self.end_value,
            interval=self.interval, unit=self.unit
        )
